__NUXT_JSONP__("/ar/school-calendar", {data:[{details:{slug:"ar",pageTitle:"تقويم مدرسة MLI | Mentor Language Institute",pageDescription:"The program strating date varies depending on F1 or Non F1 students.",title:"تقويم مدرسة MLI",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003Eالأصفر\u003C\u002Ffont\u003E: تاريخ بدء البرنامج (الوحدة)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003Eلون أخضر\u003C\u002Ffont\u003E : لا توجد مدرسة (عطلة)"],schoolCalendar:{title:"التقويم المدرسي (مواعيد بدء البرنامج)",description:["يختلف تاريخ تسلسل البرنامج اعتمادًا على طلاب F1 أو غير F1."],lists:[{key:"الطلاب من غير F1 الذين لا يحصلون على تأشيرة طالب.",value:["يمكنهم بدء برنامجهم في أي يوم اثنين. \u003Cbr\u002F\u003E إذا كان يوم الاثنين عطلة ، فسيكون تاريخ بدء البرنامج هو الثلاثاء لهذا الأسبوع."]},{key:"طلاب F1 الحاصلين على تأشيرة طالب.",value:["يمكن أن تبدأ في أيام الاثنين المحددة. (مميز باللون الأصفر في التقويم).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"الأسئلة المتداولة حول مواعيد الوصول إلى الولايات المتحدة.",lists:[{key:"\u003Cb\u003Eكم يومًا قبل تاريخ بدء البرنامج يمكن للطالب دخول الولايات المتحدة؟\u003C\u002Fb\u003E",value:["لا تطلب MLI من طلابنا القدوم إلى الولايات المتحدة عددًا محددًا من الأيام مقدمًا. \u003Cbr\u003E ومع ذلك ، عادةً ما يدخل طلابنا إلى الولايات المتحدة قبل يوم أو يومين من تواريخ بدء البرنامج."],note:"ملاحظة: يُسمح للطلاب الدوليين بدخول الولايات المتحدة قبل 30 يومًا من تواريخ بدء البرنامج."},{key:"\u003Cb\u003Eهل يمكن الانتقال إلى السكن قبل مواعيد بدء البرنامج؟\u003C\u002Fb\u003E",value:["نعم. يمكننا ترتيب نقل إقامتك في التاريخ كأي تاريخ. \u003Cbr\u003E إذا كانت هناك أسئلة أخرى ، فلا تتردد في استشارتنا."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Far",extension:".json",createdAt:"2026-10-22T16:31:30.860Z",updatedAt:"2026-04-24T11:47:24.243Z"}}],fetch:{},mutations:void 0});